"""Read-only independent V22 audit. No FE or producer/checker imports."""
import csv, gc, hashlib, json, math, pathlib, time
import numpy as np
from scipy import sparse
R=pathlib.Path('/home/fenics/Projects/NN-Lab-V2'); T=R/'docs/task042extra_feinn_5nm/outcomes/records'; A=R/'benchmarks/artifacts/task42extra'
t0=time.monotonic(); checked={}; exceptions=[]
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(4*1024*1024),b''): h.update(b)
 return h.hexdigest()
def bind(b):
 p=pathlib.Path(b['path']);p=p if p.is_absolute() else R/p
 if str(p) not in checked: checked[str(p)]=sha(p) if p.is_file() else None
 if checked[str(p)]!=b['sha256']: exceptions.append(dict(path=str(p),expected=b['sha256'],actual=checked[str(p)]))
 return p
def walk(o):
 if isinstance(o,dict):
  if isinstance(o.get('path'),str) and isinstance(o.get('sha256'),str): bind(o)
  for v in o.values(): walk(v)
 elif isinstance(o,list):
  for v in o: walk(v)
def load(p): return json.loads(pathlib.Path(p).read_text())
def index(stage): return load(sorted(A.glob('index_'+stage+'_attempt*.json'))[-1])
def npz(p):
 with np.load(p,allow_pickle=False) as z:return {k:z[k] for k in z.files}
def norm(x):return np.sqrt(np.sum(abs(x)**2,dtype=np.longdouble))
for p in sorted(T.glob('*_v22.json')):walk(load(p))
idx=index('v22_corrected_compare'); roles=load(bind(idx['files']['role_indices']));walk(roles)
ints=npz(bind(idx['files']['integrals'])); obs={}; physics=[]
for role,rec in roles.items():
 a=npz(bind(rec['files']['observables'])); obs[role]=a
 w=a['quadrature_weights_nm3']; k0=float(a['k0']);mu=complex(a['mu_r'])
 e=a['mode_e']*a['outgoing_boundary'][:,None];h=np.cross(a['mode_k'],e)/(k0*mu)
 power=np.maximum(0,np.real(np.cross(e,h.conj()))[:,2]*np.where(a['mode_keys'][:,0]=='top',1,-1)*float(a['port_area'])/(2*float(a['incident_power'])))
 assert np.max(abs(power-a['per_level_power']))<1e-12
 rr=float(sum(power[a['mode_keys'][:,0]=='top']));tt=float(sum(power[a['mode_keys'][:,0]=='bottom']))
 av=float(.5*k0*np.sum(a['cell_epsilon'].imag[:,None]*w*np.sum(abs(a['total_E'])**2,axis=2))/float(a['incident_power']))
 norms=[float(np.sqrt(np.sum(w*np.sum(abs(a[k])**2,axis=2)))/(k0 if 'curl' in k else 1)) for k in ('total_E','total_curl','scattered_E','scattered_curl')]
 assert np.allclose(norms,a['physical_field_norms'],rtol=1e-12,atol=1e-14)
 if 'total_E_hi' in a:
  for k in ('total_E','total_curl','total_H'): assert np.array_equal(a[k],a[k+'_hi'].astype(np.clongdouble)+a[k+'_lo'].astype(np.clongdouble))
 physics.append(dict(role=role,R=rr,T=tt,A_volume=av,closure=abs(rr+tt+av-1),norms=norms))
counts={};pairs={}
for pair in ('old_E3_vs_new_E3','old_E4_vs_new_E4','new_E3_vs_new_E4'):
 aa,bb=pair.split('_vs_');a,b=obs[aa],obs[bb];assert np.array_equal(a['mode_keys'],b['mode_keys']);modes={}
 for k in ('total_projection','scattered_projection','outgoing_origin','outgoing_boundary'):
  d=abs(a[k]-b[k]);den=np.maximum(abs(b[k]),1e-12);rel=d/den;j=int(np.argmax(rel));modes[k]=dict(key=a['mode_keys'][j].tolist(),absolute=float(d[j]),denominator=float(den[j]),relative=float(rel[j]),over_1e3=int(sum(rel>1e-3)))
 q15,q30=ints[pair+'_q15'],ints[pair+'_q30'];pairs[pair]=dict(fields=(np.sqrt(q15[0,:,0])/np.maximum(np.sqrt(q15[0,:,1]),1e-12)).tolist(),qdrift=float(np.max(abs(q15-q30)/np.maximum(abs(q30),1e-24))),modes=modes)
for label in ('corrected_channels','corrected_samples','corrected_regions','corrected_mode_errors'):
 rows=list(csv.DictReader((T/(label+'_v22.csv')).open()));counts[label]=len(rows)
 for row in rows:
  if label=='corrected_channels':
   key=[row[k] for k in ('side','m','n','polarization')];role=row['role'];role=role if role in obs else 'new_'+role;a=obs[role];j=int(np.flatnonzero(np.all(a['mode_keys']==key,axis=1))[0])
   for k in ('total_projection','scattered_projection','outgoing_origin','outgoing_boundary'):
    assert complex(float(row[k+'_real']),float(row[k+'_imag']))==complex(a[k][j])
   assert float(row['power'])==a['per_level_power'][j]
  elif label=='corrected_samples':
   role=row['role'];a=obs[role if role in obs else 'new_'+role];j=int(row['point'])
   for v,ax in enumerate(('x','y','z')):
    for k in ('total_E','total_H','scattered_E','scattered_H'):assert complex(float(row[k+'_'+ax+'_real']),float(row[k+'_'+ax+'_imag']))==complex(a['selected_'+k][j,v])
  elif label=='corrected_regions':
   ri=['all','air','substrate','grating','notch','interface_band'].index(row['region']);qi=['total_E','total_scaled_curl','scattered_E','scattered_scaled_curl'].index(row['quantity']);v=ints[row['pair']+'_q15'][ri,qi]
   assert math.isclose(float(row['relative']),float(np.sqrt(v[0])/max(np.sqrt(v[1]),1e-12)),rel_tol=2e-12)
  else:
   a,b=(obs[k] for k in row['pair'].split('_vs_'));key=[row[k] for k in ('side','m','n','polarization')];j=int(np.flatnonzero(np.all(a['mode_keys']==key,axis=1))[0]);family=row.get('quantity',row.get('channel',row.get('family')))
   if family is None: raise ValueError(('mode CSV schema',list(row)))
   rel=abs(a[family][j]-b[family][j])/max(abs(b[family][j]),1e-12);assert math.isclose(float(row['relative']),float(rel),rel_tol=1e-12,abs_tol=1e-18)
attrib={}
for k in ('total_E','total_curl','scattered_E','scattered_curl'):
 a,b,c,d=(obs[r] for r in ('old_E3','old_E4','new_E3','new_E4'))
 assert all(np.array_equal(a['quadrature_points_nm'],o['quadrature_points_nm']) and np.array_equal(a['quadrature_weights_nm3'],o['quadrature_weights_nm3']) for o in (b,c,d))
 scale=float(a['k0']) if 'curl' in k else 1; w=(a[k]-b[k])/scale;u=(c[k]-a[k])/scale;v=(d[k]-b[k])/scale; weights=a['quadrature_weights_nm3']
 def inner(x,y):return np.sum(weights*np.sum(x.conj()*y,axis=2),dtype=np.clongdouble).real
 terms=[inner(w,w),inner(u,u),inner(v,v),2*inner(w,u),-2*inner(w,v),-2*inner(u,v)]
 new=inner(w+u-v,w+u-v);attrib[k]=dict(terms=list(map(float,terms)),closure=float(abs(sum(terms)-new)),relative_norm_change=float(np.sqrt(new/terms[0])-1),triangle_upper=float((np.sqrt(terms[1])+np.sqrt(terms[2]))/np.sqrt(terms[0])))
del obs,a,b,c,d,w,u,v;gc.collect()
frozen=load(bind(index('v22_frozen_port_audit')['files']['role_indices']));walk(frozen)
residuals={};conditioning={}
for role,rec in frozen.items():
 path=pathlib.Path(rec['files']['native']['path']).parent; z=npz(path/'frozen_residual_terms.npz')
 delta=z['old_residual']+z['operator_delta']-z['RHS_delta']-z['new_residual']
 residuals[role]=dict(native=float(norm(z['new_residual'])/norm(z['native_f'])),identity_absolute=float(norm(delta)),identity_scaled=float(norm(delta)/max(norm(z['new_residual']),np.longdouble(1e-300))))
 # A row condition estimate diagnoses sensitivity, never replaces a gate.
 surfaces=npz(path/'surface_oracles.npz');Ds={};Hs={}
 for name in ('analytic','oracle1','oracle2'):
  Ds[name]=sparse.csr_matrix((surfaces[name+'_D_data'],surfaces[name+'_D_indices'],surfaces[name+'_D_indptr']),shape=tuple(surfaces[name+'_D_shape'])).astype(np.clongdouble)
  Hs[name]=surfaces[name+'_H'].astype(np.longdouble)
 states={'frozen':npz(path/'affine_state.npz')}
 if role!='O3': states['corrected']=npz(index('v22_'+role.lower()+'_correction')['files']['field']['path'])
 roleout={}
 for state_label,state in states.items():
  for label,c in [('scattered',state['c_scattered'].astype(np.clongdouble)),('background',state['background'].astype(np.clongdouble)),('total',state['total_hi'].astype(np.clongdouble)+state['total_lo'].astype(np.clongdouble))]:
   products={};cond={};bounds={}
   for name,D in Ds.items():
    products[name]=(D@c)/Hs[name]
    cond[name]=np.asarray(abs(D)@abs(c))/np.maximum(abs(D@c),np.longdouble(1e-300))
   x,y,z2=(products[n] for n in ('analytic','oracle1','oracle2'));da=abs(x-y);den=np.maximum(abs(y),np.longdouble(1e-12));j=int(np.argmax(da/den))
   # Row-wise coefficient perturbation bound using the actual two oracles.
   bound=(abs(Ds['oracle1']-Ds['oracle2'])@abs(c))/Hs['oracle1']
   normalized_y=y*np.sqrt(Hs['oracle1']);normalized_delta=(y-z2)*np.sqrt(Hs['oracle1'])
   roleout[state_label+'_'+label]=dict(analytic_vs_oracle1=float(norm(x-y)/max(norm(y),np.longdouble(1e-12))),oracle1_vs_oracle2=float(norm(y-z2)/max(norm(z2),np.longdouble(1e-12))),boundary_scaled_oracle_disagreement=float(norm(normalized_delta)/max(norm(normalized_y),np.longdouble(1e-12))),worst_index=j,worst_relative=float(da[j]/den[j]),worst_condition=float(cond['oracle1'][j]),condition_median=float(np.median(cond['oracle1'])),condition_max=float(np.max(cond['oracle1'])),binary64_u_condition_max=float(np.max(cond['oracle1'])*2**-53),oracle_perturbation_bound_global=float(norm(bound)/max(norm(y),np.longdouble(1e-12))),H_min=float(min(Hs['oracle1'])),H_max=float(max(Hs['oracle1'])))
 conditioning[role]=roleout
 del surfaces,Ds,Hs,states;gc.collect()
result=dict(schema='review_v22.independent_saved_array_audit.v1',bindings=checked,binding_count=len(checked),binding_exceptions=exceptions,physics=physics,csv_counts=counts,pairs=pairs,attribution=attrib,residuals=residuals,conditioning=conditioning,conditioning_arithmetic='extended complex accumulation of saved binary64 matrices; diagnostic only, no physical error certificate',FE_solve_training=0,seconds=time.monotonic()-t0)
(R/'tmp/task42extra/review_v22_raw_audit.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='bindings'},indent=2))

