"""Independent finite-array precision witnesses, no new FE or solve."""
import hashlib,json,pathlib,subprocess,time
from decimal import Decimal,localcontext
import numpy as np
from scipy import sparse
from scipy.special import spherical_jn
from numpy.polynomial.legendre import leggauss,legvander
R=pathlib.Path('/home/fenics/Projects/NN-Lab-V2');A=R/'benchmarks/artifacts/task42extra';start=time.monotonic()
def load(p):return json.loads(pathlib.Path(p).read_text())
def npz(p):
 with np.load(p,allow_pickle=False) as z:return {k:z[k] for k in z.files}
def index(s):return load(sorted(A.glob('index_'+s+'_attempt*.json'))[-1])
def norm(a):return np.sqrt(np.sum(abs(a)**2,dtype=np.longdouble))
raw=load(R/'tmp/task42extra/review_v22_raw_audit.json');resolved=[]
commits=subprocess.check_output(['git','rev-list','19b3198552efdf87281dd0c97abb7fdd1ab9642e..HEAD'],text=True).splitlines()
for ex in raw['binding_exceptions']:
 if ex in [v['exception'] for v in resolved]:continue
 p=pathlib.Path(ex['path']);name=str(p.relative_to(R));matches=[]
 if name.startswith(('src/','benchmarks/')) and p.is_file():
  for c in commits:
   q=subprocess.run(['git','show',c+':'+name],capture_output=True)
   if q.returncode==0 and hashlib.sha256(q.stdout).hexdigest()==ex['expected']:matches.append(c)
 resolved.append(dict(exception=ex,historical_blob_matches=matches,status='HISTORICAL_SOURCE_RESOLVED' if matches else 'DOCUMENTED_MISSING_INPUT' if ex['actual'] is None else 'UNRESOLVED'))
equations={}; exact={}
frozen=load(index('v22_frozen_port_audit')['files']['role_indices']['path'])
for role in ('E3','E4'):
 idx=index('v22_'+role.lower()+'_correction');a=npz(idx['files']['native']['path']);s=npz(idx['files']['field']['path']);n=len(a['masters']);nc,dim=a['cell_dofs'].shape
 E=sparse.coo_matrix((a['evals'],(a['erows'],a['eids'])),shape=(nc*dim,n)).tocsr();B=sparse.coo_matrix((a['bv'],(a['br'],a['bp'])),shape=(n,len(a['H']))).tocsr();D=sparse.coo_matrix((a['dv'],(a['dp'],a['dr'])),shape=(len(a['H']),n)).tocsr()
 def vol(c):
  local=(E@c).reshape(nc,dim);v=np.empty_like(local)
  for cls,tensor in enumerate(a['F']):
   ids=np.flatnonzero(a['classes']==cls);v[ids]=np.einsum('ij,cj->ci',tensor,local[ids],optimize=False)
  return E.conj().T@v.ravel()
 c=s['c_scattered'];al=s['alpha_scattered'];f=a['g']-B@(a['gp']/a['H']);res=vol(c)+B@((D@c)/a['H'])-f
 equations[role]=dict(native=float(norm(res)/norm(f)),augmented=float(norm(np.r_[vol(c)+B@al-a['g'],-D@c+a['H']*al-a['gp']])/norm(np.r_[a['g'],a['gp']])))
 surf=npz(pathlib.Path(frozen[role]['files']['native']['path']).parent/'surface_oracles.npz');ds={}
 for key in ('analytic','oracle1','oracle2'):
  ds[key]=sparse.csr_matrix((surf[key+'_D_data'],surf[key+'_D_indices'],surf[key+'_D_indptr']),shape=tuple(surf[key+'_D_shape']))
 cols={};worst={int(v['worst_index']) for k,v in raw['conditioning'][role].items() if k.startswith('corrected')}
 worst.update(np.argsort(abs(s['alpha_scattered']))[-3:].tolist())
 def decdot(mat,j,vec):
  rr=Decimal(0);ii=Decimal(0)
  for q in range(mat.indptr[j],mat.indptr[j+1]):
   d=mat.data[q];x=vec[mat.indices[q]];u,v,xr,xi=[Decimal.from_float(float(t)) for t in (d.real,d.imag,x.real,x.imag)]
   rr+=u*xr-v*xi;ii+=u*xi+v*xr
  return rr,ii
 def cv(r,i,h):return np.clongdouble(str(r/h))+np.clongdouble(1j)*np.clongdouble(str(i/h))
 with localcontext() as ctx:
  ctx.prec=110
  for j in sorted(worst):
   vals={}
   for key,dd in ds.items():
    h=Decimal.from_float(float(surf[key+'_H'][j]));r,i=decdot(dd,j,s['c_scattered']);br,bi=decdot(dd,j,s['background']);vals[key]=dict(scattered=cv(r,i,h),background=cv(br,bi,h),total=cv(r+br,i+bi,h))
   cols[str(j)]={}
   for label in ('scattered','background','total'):
    x,y,z=(vals[k][label] for k in ('analytic','oracle1','oracle2'));den=max(abs(z),np.longdouble(1e-12));cols[str(j)][label]=dict(oracle1_vs_oracle2_relative=float(abs(y-z)/den),oracle1_vs_oracle2_absolute=float(abs(y-z)),denominator=float(den),analytic_vs_oracle1=float(abs(x-y)/max(abs(y),np.longdouble(1e-12))),oracle2=[float(z.real),float(z.imag)])
 exact[role]=cols
moments=[]
for ny in (4,36):
 z=np.pi*35/ny;p=6;reference=np.array([2*1j**l*spherical_jn(l,z) for l in range(p+1)]);rules={}
 for degree,n in ((30,16),(60,31),(126,64)):
  nodes,w=leggauss(n);v=(w*np.exp(1j*z*nodes))@legvander(nodes,p);err=abs(v-reference);rules[str(degree)]=dict(points=n,absolute=err.tolist(),max_absolute=float(max(err)),worst_degree=int(np.argmax(err)))
 moments.append(dict(y_segments=ny,mode_n=35,half_phase=z,polynomial_degrees=list(range(7)),rules=rules,scope='one-dimensional scalar polynomial moment witness; not all AUTO keys or assembled FE'))
out=dict(schema='review_v22.precision_and_equation_audit.v1',resolved_bindings=resolved,equations=equations,decimal110_selected_rows=exact,scalar_moments=moments,seconds=time.monotonic()-start,FE_solve_training=0)
(R/'tmp/task42extra/review_v22_precision_audit.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
